---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Onboarding checklist: First steps with a progress ring, and the agent can do some for you.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change onboarding-checklist.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './onboarding-checklist.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" draws it in the Soft style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft") */
  'data-style'?: 'soft';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', 'bare', className]} data-c="onboarding-checklist" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="obx">
  <div class="obx-h"><span class="obx-rw"><svg class="obx-ring" viewBox="0 0 40 40"><circle cx="20" cy="20" r="16" class="tr"/><circle cx="20" cy="20" r="16" class="fl"/></svg><span class="obx-rk"><svg class="i xs"><use href="#i-check"/></svg></span></span><div class="obx-ht"><b>Get set up</b><span class="muted obx-st">0 of 5 done</span></div><button class="ib obx-min" aria-label="Collapse" data-tip="Collapse"><svg class="i xs"><use href="#i-chev-d"/></svg></button></div>
  <div class="fold obx-fold"><div><div class="obx-list"></div></div></div>
</div>
  </Fragment></div>
</div>
<script>
  import './onboarding-checklist.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Onboarding checklist ---------- */
/* posted in the chat: no container of its own; with .panel it becomes a card */
.obx{padding:var(--dm-s-3) 0;display:flex;flex-direction:column;gap:6px}
.obx.panel{padding:var(--dm-s-3)}
.obx-h{display:flex;align-items:center;gap:var(--dm-s-3);padding:2px 0}
.obx-rw{position:relative;width:38px;height:38px;flex:none}
.obx-ring{width:38px;height:38px;transform:rotate(-90deg);display:block}
/* everything done: a green check grows in the middle of the ring */
.obx-rk{position:absolute;inset:7px;border-radius:50%;background:var(--dm-accent);color:var(--dm-on-accent);display:grid;place-items:center;opacity:0;transform:scale(.4);transition:opacity .35s var(--dm-ease),transform .55s var(--dm-ease)}
.obx-rw.full .obx-rk{opacity:1;transform:none}
/* round in Blueprint too: it sits inside the round ring */
.obx .obx-rw .obx-rk{border-radius:50%!important}
.obx-ring circle{fill:none;stroke-width:3.5;stroke-linecap:round}
.obx-ring .tr{stroke:var(--dm-line)}
.obx-ring .fl{stroke:var(--dm-accent-mark,var(--dm-accent));stroke-dasharray:100.5;stroke-dashoffset:100.5;transition:stroke-dashoffset .8s var(--dm-ease),stroke .4s}
.obx-ring.full .fl{stroke:var(--dm-accent-mark,var(--dm-accent))}
.obx-ht{flex:1;display:flex;flex-direction:column;font-size:14px}
.obx-ht b{font-weight:500}
.obx-st{font-size:12px}
.obx-min svg{transition:transform .4s var(--dm-ease)}
.obx-min.shut svg{transform:rotate(-90deg)}
/* each checkbox sits under the middle of the ring, and the titles line up with the heading */
.obx-list{display:flex;flex-direction:column;padding-top:var(--dm-s-1)}
.obx-s{display:flex;align-items:center;gap:21px;padding:var(--dm-s-2) var(--dm-s-2) var(--dm-s-2) 9px;border-radius:calc(10px * var(--dm-rk));font-size:13px;cursor:pointer;transition:background .2s}
.obx-s.run{cursor:default}
@media (hover:hover) and (pointer:fine){.obx-s:hover{background:var(--dm-row)}}
/* an open step's box is a dimmed grey ring, never a dark one; it still holds 3:1 */
.obx-ck{width:20px;height:20px;border-radius:50%;box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-pick-on) 50%,transparent);display:grid;place-items:center;color:transparent;flex:none;transition:background .3s var(--dm-ease),box-shadow .3s,color .3s}
.obx-ck svg{transform:scale(.4);transition:transform .4s var(--dm-ease)}
.obx-s.done .obx-ck{background:var(--dm-accent);box-shadow:none;color:var(--dm-on-accent)}
.obx-s.done .obx-ck svg{transform:none}
.obx-s.run .obx-ck{box-shadow:none;color:var(--dm-accent-fg,var(--dm-accent))}
.obx-s .t{flex:1;display:flex;flex-direction:column;min-width:0}
.obx-s .t span{font-size:12px;color:var(--dm-muted)}
.obx-s.done .t>b{color:var(--dm-muted);text-decoration:line-through;text-decoration-color:var(--dm-faint)}
.obx-s .t>b{font-weight:400;transition:color .3s}
.obx-s .pill{opacity:0;transition:opacity .2s}
.obx-s .pill:focus-visible{opacity:1}
@media (hover:hover) and (pointer:fine){.obx-s:hover .pill{opacity:1}}
.obx-s.done .pill,.obx-s.run .pill{display:none}
.obx-dn{display:flex;align-items:center;gap:var(--dm-s-2);padding:10px;border-radius:var(--dm-r-in);background:var(--dm-accent-bg);color:var(--dm-fg);font-size:13px;margin-top:var(--dm-s-1)}
.obx-dn svg{color:var(--dm-accent-fg,var(--dm-accent));flex:none}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, enter, html, stagger, swap } from '../core/core.js';
DM.def('onboarding-checklist', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{chev}', I('chev-d','xs')).replace('{check}', I('check','xs'));
  const S = [['Create your workspace','Done when you signed up',1,0],['Connect Figma','So the agent can read your frames',0,1],['Import your tokens','Colours, type and spacing',0,1],['Invite a teammate','Design is better together',0,0],['Run your first audit','Takes about a minute',0,1]];
  const list = $('.obx-list', r), st = $('.obx-st', r), ring = $('.obx-ring', r), rw = $('.obx-rw', r), fl = $('.obx-ring .fl', r);
  list.innerHTML = S.map((s, i) => `<div class="obx-s${s[2] ? ' done' : ''}" data-i="${i}"><button class="obx-ck" role="checkbox" aria-checked="${!!s[2]}" aria-label="${s[0]}">${I('check','xs')}</button><span class="t"><b>${s[0]}</b><span>${s[1]}</span></span>${s[3] ? `<button class="pill soft sm">${I('spark','xs')}Do it for me</button>` : ''}</div>`).join('');
  const rows = $$('.obx-s', list);
  function tally(){ const n = S.filter(s => s[2]).length; fl.style.strokeDashoffset = 100.5 * (1 - n / S.length); ring.classList.toggle('full', n === S.length); rw.classList.toggle('full', n === S.length); swap(st, n === S.length ? 'All done. Nice work' : n + ' of ' + S.length + ' done');
    if (n === S.length && !$('.obx-dn', list)){ const d = html(`<div class="obx-dn">${I('ok','xs')}You are all set. The agent will suggest what to try next.</div>`); list.appendChild(d); enter(d); } else if (n < S.length) $('.obx-dn', list)?.remove(); }
  const set = (i, v) => { S[i][2] = v; rows[i].classList.toggle('done', v); $('.obx-ck', rows[i]).setAttribute('aria-checked', v); tally(); };
  rows.forEach((row, i) => {
    $('.obx-ck', row).onclick = () => set(i, !S[i][2]);
    // the whole row ticks the step, not only its checkbox (its button does its own thing, and a running step waits)
    row.onclick = e => { if (e.target.closest('.obx-ck, .pill') || row.classList.contains('run')) return; set(i, !S[i][2]); };
    const p = $('.pill', row); if (p) p.onclick = () => c.run(async () => { row.classList.add('run'); const ck = $('.obx-ck', row); ck.innerHTML = '<span class="spin" style="width:14px;height:14px"></span>'; const sp = $('.t span', row), was = sp.textContent; swap(sp, 'The agent is on it'); sp.classList.add('shim');
      await c.wait(1400); ck.innerHTML = I('check','xs'); row.classList.remove('run'); sp.classList.remove('shim'); swap(sp, was); set(i, 1); });
  });
  const mn = $('.obx-min', r); mn.onclick = () => { const s = $('.obx-fold', r).classList.toggle('shut'); mn.classList.toggle('shut', s); mn.dataset.tip = s ? 'Expand' : 'Collapse'; };
  stagger(rows, 50); c.later(200, tally);
  // the preview has the agent connect Figma once on its own, unless you take over first
  c.auto(1300, () => $('.pill', rows[1]).click());
});
